<?php
namespace App\Controllers;
use App\Libraries\AuditLogService;use App\Libraries\PlanQuotaService;use App\Libraries\WorkspaceProvisioner;use App\Models\UserModel;use App\Support\Uuid;
class Accounts extends BaseController
{
    public function index(): string { $u=current_user();$this->assertManager($u['account_type']);$b=db_connect()->table('users')->select('id,uuid,first_name,last_name,email,account_type,company_name,status,reseller_id')->where('deleted_at',null);if(in_array($u['account_type'],['reseller','reseller_team'],true))$b->where('reseller_id',$u['account_type']==='reseller'?$u['id']:$u['reseller_id']);elseif($u['account_type']==='platform_team')$b->where('parent_user_id',$u['parent_user_id']?:$u['id']);return$this->page('accounts/index',['title'=>'Accounts','active'=>'accounts','accounts'=>$b->orderBy('id','DESC')->get()->getResultArray(),'allowedTypes'=>$this->allowedTypes($u['account_type'])]); }
    public function create(){ $current=current_user();$this->assertManager($current['account_type']);$type=(string)$this->request->getPost('account_type');if(!in_array($type,$this->allowedTypes($current['account_type']),true))return redirect()->back()->with('error','You cannot create that account type.');$rules=['first_name'=>'required|min_length[2]|max_length[100]','last_name'=>'permit_empty|max_length[100]','email'=>'required|valid_email|max_length[190]|is_unique[users.email]','password'=>'required|min_length[10]','company_name'=>'permit_empty|max_length[150]'];if(!$this->validateData($this->request->getPost(),$rules))return redirect()->back()->withInput()->with('error',implode(' ',$this->validator->getErrors()));$levels=['platform_team'=>2,'reseller'=>3,'reseller_team'=>4,'customer'=>5];$resellerId=in_array($current['account_type'],['reseller','reseller_team'],true)?($current['account_type']==='reseller'?$current['id']:$current['reseller_id']):null;$model=new UserModel();$id=$model->insert(['uuid'=>Uuid::v4(),'account_level'=>$levels[$type],'account_type'=>$type,'user_type'=>$type==='platform_team'?'admin_team':$type,'parent_user_id'=>$current['id'],'reseller_id'=>$resellerId,'first_name'=>$this->request->getPost('first_name'),'last_name'=>$this->request->getPost('last_name'),'username'=>$this->request->getPost('first_name'),'email'=>strtolower(trim((string)$this->request->getPost('email'))),'password_hash'=>password_hash((string)$this->request->getPost('password'),PASSWORD_DEFAULT),'company_name'=>$this->request->getPost('company_name')?:null,'status'=>'active','active'=>1,'must_change_password'=>1,'created_by'=>$current['id']]);if(!$id)return redirect()->back()->withInput()->with('error',implode(' ',$model->errors()));$created=$model->find($id);if($type==='reseller')db_connect()->table('reseller_profiles')->insert(['user_id'=>$id,'brand_name'=>$created['company_name']?:$created['first_name'],'created_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);elseif($type==='customer')(new WorkspaceProvisioner())->ensureForUser($created);(new AuditLogService())->record('user.created',$current,['account_type'=>$type],'user',$created['uuid']);return redirect()->to(portal_url('accounts'))->with('success','Account created successfully.'); }
    public function permissions(string $uuid):string { $current=current_user();$target=(new UserModel())->where('uuid',$uuid)->first();if(!$target||!$this->canManage($current,$target))throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();$db=db_connect();$defs=$db->table('permission_definitions')->orderBy('module')->orderBy('label')->get()->getResultArray();$states=array_column($db->table('user_permission_overrides')->where('user_id',$target['id'])->get()->getResultArray(),'state','permission_key');$workspaces=$this->availableWorkspaces($current);$assigned=array_column($db->table('user_workspace_assignments')->where('user_id',$target['id'])->get()->getResultArray(),'workspace_id');return$this->page('accounts/permissions',['title'=>'Individual permissions','active'=>'accounts','target'=>$target,'definitions'=>$defs,'states'=>$states,'workspaces'=>$workspaces,'assigned'=>$assigned]); }
    public function savePermissions(string $uuid){$current=current_user();$target=(new UserModel())->where('uuid',$uuid)->first();if(!$target||!$this->canManage($current,$target))throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();$db=db_connect();$submitted=(array)$this->request->getPost('permissions');$allowed=array_column($db->table('permission_definitions')->select('permission_key')->get()->getResultArray(),'permission_key');$now=date('Y-m-d H:i:s');$db->transStart();foreach($allowed as$key){$state=in_array($submitted[$key]??'inherit',['allow','deny','inherit'],true)?$submitted[$key]:'inherit';$old=$db->table('user_permission_overrides')->where(['user_id'=>$target['id'],'permission_key'=>$key])->get()->getRowArray();if($state==='inherit'){$db->table('user_permission_overrides')->where(['user_id'=>$target['id'],'permission_key'=>$key])->delete();}elseif($old){$db->table('user_permission_overrides')->where('id',$old['id'])->update(['state'=>$state,'changed_by'=>$current['id'],'updated_at'=>$now]);}else{$db->table('user_permission_overrides')->insert(['user_id'=>$target['id'],'permission_key'=>$key,'state'=>$state,'changed_by'=>$current['id'],'created_at'=>$now,'updated_at'=>$now]);}if(($old['state']??'inherit')!==$state)$db->table('permission_change_history')->insert(['user_id'=>$target['id'],'permission_key'=>$key,'old_state'=>$old['state']??'inherit','new_state'=>$state,'changed_by'=>$current['id'],'created_at'=>$now]);}$db->table('user_workspace_assignments')->where('user_id',$target['id'])->delete();$available=array_column($this->availableWorkspaces($current),'id');foreach((array)$this->request->getPost('workspace_ids') as$wid)if(in_array((int)$wid,array_map('intval',$available),true))$db->table('user_workspace_assignments')->insert(['user_id'=>$target['id'],'workspace_id'=>(int)$wid,'assigned_by'=>$current['id'],'created_at'=>$now]);$db->transComplete();if(!$db->transStatus())return redirect()->back()->with('error','Unable to save permissions.');(new AuditLogService())->record('permissions.changed',$current,['target_uuid'=>$target['uuid']],'user',$target['uuid']);return redirect()->back()->with('success','Permissions and workspace access updated. The user must sign in again.'); }
    private function canManage(array$c,array$t):bool{if($c['id']===$t['id'])return false;return match($c['account_type']){'platform_admin'=>true,'platform_team'=>$t['parent_user_id']==$c['parent_user_id']||$t['parent_user_id']==$c['id'],'reseller','reseller_team'=>(int)$t['reseller_id']===(int)($c['account_type']==='reseller'?$c['id']:$c['reseller_id']),'customer'=>in_array($c['workspace_role'],['owner','administrator'],true)&&(int)$t['workspace_id']===(int)$c['workspace_id'],default=>false};}
    private function availableWorkspaces(array$u):array{$b=db_connect()->table('workspaces')->select('id,uuid,company_name,name');if($u['account_type']==='reseller')$b->where('reseller_id',$u['id']);elseif($u['account_type']==='reseller_team')$b->join('user_workspace_assignments a','a.workspace_id=workspaces.id')->where('a.user_id',$u['id']);elseif($u['account_type']==='customer')$b->where('id',$u['workspace_id']);return$b->orderBy('company_name')->get()->getResultArray();}
    private function allowedTypes(string $t):array{return match($t){'platform_admin'=>['platform_team','reseller','customer'],'platform_team'=>['reseller','customer'],'reseller','reseller_team'=>['reseller_team','customer'],default=>[]};}private function assertManager(string $t):void{if($this->allowedTypes($t)===[])throw \CodeIgniter\Exceptions\PageNotFoundException::forPageNotFound();}
}
